      {
       "contentTypeKey": "0b203fa8-515c-4763-8e59-ab85aa5600e1",
       "key": "522eef50-0ee7-4f1e-a942-6fe9c69e9881",
       "values": [
        {
         "editorAlias": "Umbraco.TextBox",
         "culture": null,
         "segment": null,
         "alias": "eyebrow",
         "value": "Field notes · 01"
        },
        {
         "editorAlias": "Umbraco.TextBox",
         "culture": null,
         "segment": null,
         "alias": "heading",
         "value": "Why MCP turns useful context into useful work"
        },
        {
         "editorAlias": "Umbraco.TextArea",
         "culture": null,
         "segment": null,
         "alias": "introduction",
         "value": "An assistant becomes much more helpful when it can reach the right tools and current information through a consistent interface."
        },
        {
         "editorAlias": "Umbraco.MediaPicker3",
         "culture": null,
         "segment": null,
         "alias": "image",
         "value": [
          {
           "key": "66b17691-7b49-4b0b-92de-54bb459508ec",
           "mediaKey": "64329394-1987-4f31-8ad8-0632956aa6f3",
           "mediaTypeAlias": "Image",
           "crops": [],
           "focalPoint": null
          }
         ]
        }
       ]
      },
      {
       "contentTypeKey": "2e1434fa-de4a-433d-94e9-2ef609213c90",
       "key": "da331bed-75b3-43f3-b766-11d304acb54b",
       "values": [
        {
         "editorAlias": "Umbraco.TextBox",
         "culture": null,
         "segment": null,
         "alias": "heading",
         "value": "The gap between answering and doing"
        },
        {
         "editorAlias": "Umbraco.TextArea",
         "culture": null,
         "segment": null,
         "alias": "body",
         "value": "A model can explain a process from memory. Real work usually depends on the state of a project right now: its content, files, services and permissions. Without a connection to those systems, even a well written answer can stop one step short of the task.\nMCP gives an assistant a standard way to discover available tools and use them. The tool stays responsible for its own data and operations; the assistant can ask for the information it needs at the moment it needs it."
        }
       ]
      },
      {
       "contentTypeKey": "2e1434fa-de4a-433d-94e9-2ef609213c90",
       "key": "e835c309-6efb-40ed-bafc-a1cef163bc58",
       "values": [
        {
         "editorAlias": "Umbraco.TextBox",
         "culture": null,
         "segment": null,
         "alias": "heading",
         "value": "Context arrives with a purpose"
        },
        {
         "editorAlias": "Umbraco.TextArea",
         "culture": null,
         "segment": null,
         "alias": "body",
         "value": "A useful integration is more than a pile of text in a prompt. A server can expose focused resources and actions with clear inputs. That lets an assistant inspect a document type, find a media item or create a page in a workflow that makes sense for the project.\nThe result is a shorter path from intent to action. People can spend less time copying identifiers between screens and more time reviewing the outcome."
        }
       ]
      },
      {
       "contentTypeKey": "2e1434fa-de4a-433d-94e9-2ef609213c90",
       "key": "ac1254f3-24bd-447f-b0de-62fb22a10633",
       "values": [
        {
         "editorAlias": "Umbraco.TextBox",
         "culture": null,
         "segment": null,
         "alias": "heading",
         "value": "A local example"
        },
        {
         "editorAlias": "Umbraco.TextArea",
         "culture": null,
         "segment": null,
         "alias": "body",
         "value": "This journal was assembled through Umbraco’s local MCP server. The same connection used to inspect the content tree also created block types, imported media and published these pages. Reading the saved documents back confirmed that the block grid values were actually stored.\nThat feedback loop is the exciting part: discover, act, verify. MCP makes it practical for an assistant to work with a real system while keeping the system’s own structure in charge."
        }
       ]
      }
     ],
     "settingsData": [],
